#include <vector>

using namespace std;

class TreeAncestor {
    vector<vector<int>> up;
    int LOG;

public:
    TreeAncestor(int n, vector<int>& parent) {
        LOG = 32 - __builtin_clz(n);
        up = vector<vector<int>>(n, vector<int>(LOG, -1));

        for (int i = 0; i < n; ++i)
            up[i][0] = parent[i];

        for (int j = 1; j < LOG; ++j)
            for (int i = 0; i < n; ++i)
                if (up[i][j - 1] != -1)
                    up[i][j] = up[up[i][j - 1]][j - 1];
    }

    int getKthAncestor(int node, int k) {
        for (int j = 0; j < LOG && node != -1; ++j)
            if (k & (1 << j))
                node = up[node][j];
        return node;
    }
};
